import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

interface RequestBody {
  whatsapp_token: string;
    phone_number_id: string;
      recipient_phone: string;
      }

      interface Event {
        title: string;
          date: string;
            time: string;
              location: string;
                description: string;
                  confirmed: boolean;
                    link: string;
                    }

                    async function fetchTodayEvents(): Promise<Event[]> {
                      const response = await fetch("https://www.bachatacalendar.co.uk/", {
                          headers: {
                                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
                                    }
                                      });
                                        const html = await response.text();
                                          return parseEventsFromHTML(html);
                                          }

                                          function parseEventsFromHTML(html: string): Event[] {
                                            const events: Event[] = [];

                                                try {
                                                    // Find the TODAY section by looking for the pattern with "MAY · TODAY" or similar
                                                        const todayMatch = html.match(/(FRI|SAT|SUN|MON|TUE|WED|THU)\s+(\d{1,2})\s*[\n\s]*\w+\s*·\s*TODAY/);

                                                                if (!todayMatch) {
                                                                      return [];
                                                                          }

                                                                                  // Find where TODAY section starts
                                                                                      const todayStartIndex = html.indexOf(todayMatch[0]);

                                                                                              // Find where the next day starts (TOMORROW or IN X DAYS pattern)
                                                                                                  const nextDayRegex = /(FRI|SAT|SUN|MON|TUE|WED|THU)\s+(\d{1,2})\s*[\n\s]*\w+\s*·\s*(TOMORROW|IN \d+ DAYS)/;
                                                                                                      const nextDayMatch = html.substring(todayStartIndex + todayMatch[0].length).match(nextDayRegex);
                                                                                                          
                                                                                                              let todayEndIndex = html.length;
                                                                                                                  if (nextDayMatch) {
                                                                                                                        todayEndIndex = todayStartIndex + todayMatch[0].length + html.substring(todayStartIndex + todayMatch[0].length).indexOf(nextDayMatch[0]);
                                                                                                                            }
                                                                                                                                
                                                                                                                                    const todaySection = html.substring(todayStartIndex, todayEndIndex);
                                                                                                                                        
                                                                                                                                            // Extract events - split by event title lines
                                                                                                                                                // Pattern: Title\nat Location\nClasses/Party time entries
                                                                                                                                                    const lines = todaySection.split('\n').map(l => l.trim()).filter(l => l.length > 0);
                                                                                                                                                        
                                                                                                                                                            let i = 0;
                                                                                                                                                                while (i < lines.length) {
                                                                                                                                                                      const line = lines[i];
                                                                                                                                                                            
                                                                                                                                                                                  // Skip the day header and location marker lines
                                                                                                                                                                                        if (line.includes('MAY') || line.includes('FRI') || line.includes('SAT') || 
                                                                                                                                                                                                  line.includes('SUN') || line.includes('MON') || line.includes('TUE') || 
                                                                                                                                                                                                            line.includes('WED') || line.includes('THU')) {
                                                                                                                                                                                                                    i++;
                                                                                                                                                                                                                            continue;
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                              // Check if next line is location (starts with "at ")
                                                                                                                                                                                                                                                    if (i + 1 < lines.length && lines[i + 1].startsWith('at ')) {
                                                                                                                                                                                                                                                            const title = line;
                                                                                                                                                                                                                                                                    const location = lines[i + 1].substring(3).trim();
                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                    // Collect times (Classes/Party entries)
                                                                                                                                                                                                                                                                                            let times: string[] = [];
                                                                                                                                                                                                                                                                                                    let j = i + 2;
                                                                                                                                                                                                                                                                                                            while (j < lines.length && (lines[j] === 'Classes' || lines[j] === 'Party' || lines[j].match(/\d{1,2}:\d{2}/))) {
                                                                                                                                                                                                                                                                                                                      if (lines[j] === 'Classes' || lines[j] === 'Party') {
                                                                                                                                                                                                                                                                                                                                  // Next line should be the time
                                                                                                                                                                                                                                                                                                                                              if (j + 1 < lines.length && lines[j + 1].match(/\d{1,2}:\d{2}/)) {
                                                                                                                                                                                                                                                                                                                                                            times.push(`${lines[j]} ${lines[j + 1]}`);
                                                                                                                                                                                                                                                                                                                                                                          j += 2;
                                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                                    j++;
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                      j++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (times.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const startTime = times[0].includes('–') ? times[0].split(' ').slice(1).join(' ') : 'Check details';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const description = times.join(' | ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const hasParty = times.some(t => t.includes('Party'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const event: Event = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      title: title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  date: "May 15, 2026",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              time: startTime,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          location: location,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      description: description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  confirmed: hasParty,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              link: "https://www.bachatacalendar.co.uk/"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            events.push(event);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    i = j;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  i++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.error("Error parsing HTML:", error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return events;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function formatEventMessage(event: Event): string {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const checkmark = event.confirmed ? "✅" : "📅";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const message = `${event.title}\n${event.date}${event.time !== "Check details" ? " at " + event.time : ""}\n\n📍 ${event.location}\n\n${event.description}\n\n🔗 ${event.link}\n\n${checkmark} ${event.confirmed ? "CONFIRMED" : "TBD"}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return message;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              async function sendWhatsAppMessage(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                phoneNumberId: string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  recipientPhone: string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message: string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      accessToken: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ): Promise<boolean> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const response = await fetch(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `https://graph.instagram.com/v18.0/${phoneNumberId}/messages`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Authorization: `Bearer ${accessToken}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Content-Type": "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                messaging_product: "whatsapp",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        recipient_type: "individual",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                to: recipientPhone,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        type: "text",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                text: { preview_url: true, body: message },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return response.ok;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              serve(async (req: Request) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (req.method !== "POST") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return new Response(JSON.stringify({ error: "Method not allowed" }), {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          status: 405,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                headers: { "Content-Type": "application/json" },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const body: RequestBody = await req.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const { whatsapp_token, phone_number_id, recipient_phone } = body;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!whatsapp_token || !phone_number_id || !recipient_phone) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  JSON.stringify({ error: "Missing required parameters" }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { status: 400, headers: { "Content-Type": "application/json" } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const events = await fetchTodayEvents();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let messagesSent = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (const event of events) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const message = formatEventMessage(event);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const success = await sendWhatsAppMessage(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    phone_number_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            recipient_phone,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            whatsapp_token
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (success) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                messagesSent++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await new Promise((resolve) => setTimeout(resolve, 1000));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: messagesSent > 0 ? `Successfully sent ${messagesSent} event messages` : "No events found for today",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    events_sent: messagesSent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            events_found: events.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { status: 200, headers: { "Content-Type": "application/json" } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        JSON.stringify({ success: false, error: String(error) }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { status: 500, headers: { "Content-Type": "application/json" } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
